from __future__ import annotations

import logging
from contextlib import contextmanager
from datetime import datetime
from pathlib import Path
from typing import Any, Callable, Dict, Iterator, List, Optional, Tuple, Union

try:
    from typing import Self
except ImportError:
    from typing_extensions import Self

from zk import ZK
from zk.exception import ZKErrorConnection, ZKErrorResponse

from . import constants as consts
from .exceptions import (
    ZKConnectionError,
    ZKDeviceError,
    ZKUserNotFoundError,
)
from .models import (
    AttendanceRecord,
    CapacityInfo,
    DeviceInfo,
    FingerprintTemplate,
    LiveAccessEvent,
    NetworkParams,
    User,
)
from .rules import AccessRulesRegistry

logger = logging.getLogger("zk.client")


class ZKClient:
    """
    Synchronous Python client for ZKTeco standalone access control & time attendance devices.
    Wraps the underlying pyzk protocol with high-level Pythonic APIs, strong typing,
    device locking safety, and optional software-level access control rules.

    Usage::

        from zk import ZKClient

        with ZKClient("192.168.1.201", port=4370) as client:
            info = client.get_info()
            print(f"Connected to {info.device_name} (Firmware: {info.firmware_version})")

            users = client.list_users()
            for user in users:
                print(user.user_id, user.name)
    """

    def __init__(
        self,
        ip: str,
        port: int = consts.DEFAULT_PORT,
        timeout: int = consts.DEFAULT_TIMEOUT,
        password: int = 0,
        force_udp: bool = True,
        ommit_ping: bool = False,
        use_sdk_build_1: bool = True,
        rules: Optional[AccessRulesRegistry] = None,
        rules_storage_path: Optional[Union[str, Path]] = None,
    ):
        self.ip = ip
        self.port = port
        self.timeout = timeout
        self.password = password
        self.force_udp = force_udp
        self.ommit_ping = ommit_ping
        self.use_sdk_build_1 = use_sdk_build_1

        self._zk = ZK(
            ip,
            port=port,
            timeout=timeout,
            password=password,
            force_udp=force_udp,
            ommit_ping=ommit_ping,
        )
        self.conn = None

        # Logical software-level access rules registry
        self.rules = rules or AccessRulesRegistry(storage_path=rules_storage_path)

    # ─── Context Manager ───────────────────────────────────────────────────────

    def __enter__(self) -> Self:
        self.connect()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.disconnect()
        return False

    # ─── Connection Lifecycle ──────────────────────────────────────────────────

    def connect(self):
        """Open connection to the device and optionally apply SDK Build 1 mode."""
        if self.conn is not None:
            logger.debug(
                "Existing connection active to %s:%s; reusing.", self.ip, self.port
            )
            return self.conn

        logger.info(
            "Connecting to ZKTeco terminal %s:%s (UDP=%s)...",
            self.ip,
            self.port,
            self.force_udp,
        )
        try:
            self.conn = self._zk.connect()
        except ZKErrorConnection as exc:
            logger.error("Connection failed to %s:%s: %s", self.ip, self.port, exc)
            raise ZKConnectionError(
                f"Could not connect to {self.ip}:{self.port}: {exc}",
                host=self.ip,
                port=self.port,
            ) from exc
        except Exception as exc:
            logger.error(
                "Unexpected error connecting to %s:%s: %s", self.ip, self.port, exc
            )
            raise ZKConnectionError(
                f"Unexpected connection error to {self.ip}:{self.port}: {exc}",
                host=self.ip,
                port=self.port,
            ) from exc

        if self.use_sdk_build_1:
            try:
                self.conn.set_sdk_build_1()
            except AttributeError:
                logger.debug("set_sdk_build_1 not supported by pyzk version; skipping.")
            except Exception as exc:
                logger.warning("Failed to configure SDK build 1: %s", exc)

        return self.conn

    def disconnect(self) -> None:
        """Re-enable device UI and close socket connection."""
        if self.conn is None:
            return

        try:
            self.conn.enable_device()
        except Exception as exc:
            logger.debug("Failed to re-enable device before disconnect: %s", exc)
        finally:
            try:
                self.conn.disconnect()
            except Exception as exc:
                logger.debug(
                    "Error while disconnecting from %s:%s: %s", self.ip, self.port, exc
                )
            self.conn = None
            logger.info("Disconnected from %s:%s.", self.ip, self.port)

    @property
    def is_connected(self) -> bool:
        return self.conn is not None

    def _ensure_connected(self) -> None:
        if self.conn is None:
            raise ZKConnectionError(
                "Device is not connected. Use `with ZKClient(...) as client:` or call `.connect()` first.",
                host=self.ip,
                port=self.port,
            )

    @contextmanager
    def _device_locked(self) -> Iterator[None]:
        """
        Internal context manager that locks the keypad/screen during sensitive operations
        and guarantees the device is re-enabled upon completion.
        """
        self._ensure_connected()
        try:
            self.conn.disable_device()
        except Exception as exc:
            logger.debug("Could not lock device keypad/screen: %s", exc)

        try:
            yield
        finally:
            try:
                self.conn.enable_device()
            except Exception as exc:
                logger.debug("Could not re-enable device: %s", exc)

    def _safe_call(self, method_name: str, *args, **kwargs) -> Any:
        """Call optional pyzk method gracefully; returns None if unsupported by firmware."""
        self._ensure_connected()
        method = getattr(self.conn, method_name, None)
        if method is None:
            logger.debug(
                "Method '%s' unavailable on pyzk/firmware; returning None.", method_name
            )
            return None
        try:
            return method(*args, **kwargs)
        except (AttributeError, ZKErrorResponse) as exc:
            logger.warning(
                "Safe call to '%s' failed on %s: %s", method_name, self.ip, exc
            )
            return None

    # ─── Device Information & Health ───────────────────────────────────────────

    def get_info(self) -> DeviceInfo:
        """Retrieve hardware and firmware metadata."""
        self._ensure_connected()

        net_dict = self._safe_call("get_network_params")
        network = None
        if isinstance(net_dict, dict):
            network = NetworkParams(
                ip=net_dict.get("ip"),
                mask=net_dict.get("mask"),
                gateway=net_dict.get("gateway"),
            )

        device_time_raw = None
        try:
            device_time_raw = self.conn.get_time()
        except Exception as exc:
            logger.debug("Failed to read device time: %s", exc)

        return DeviceInfo(
            firmware_version=str(self.conn.get_firmware_version() or ""),
            platform=str(self.conn.get_platform() or ""),
            serial_number=str(self.conn.get_serialnumber() or ""),
            mac_address=str(self.conn.get_mac() or ""),
            device_time=device_time_raw,
            device_name=self._safe_call("get_device_name"),
            pin_width=self._safe_call("get_pin_width"),
            fp_version=self._safe_call("get_fp_version"),
            face_version=self._safe_call("get_face_version"),
            network=network,
        )

    def get_capacity(self) -> CapacityInfo:
        """Read memory usage and capacities from the device."""
        self._ensure_connected()
        self.conn.read_sizes()
        return CapacityInfo(
            users=getattr(self.conn, "users", None),
            users_cap=getattr(self.conn, "users_cap", None),
            fingers=getattr(self.conn, "fingers", None),
            fingers_cap=getattr(self.conn, "fingers_cap", None),
            records=getattr(self.conn, "records", None),
            records_cap=getattr(self.conn, "rec_cap", None),
        )

    # ─── Date / Time Management ────────────────────────────────────────────────

    def get_time(self) -> datetime:
        """Read current datetime set on the terminal."""
        self._ensure_connected()
        return self.conn.get_time()

    def set_time(self, when: Optional[datetime] = None) -> None:
        """Set datetime on the terminal (defaults to now)."""
        self._ensure_connected()
        when = when or datetime.now()
        logger.info("Setting device %s datetime to %s...", self.ip, when)
        self.conn.set_time(when)

    def sync_time(self) -> None:
        """Shortcut to synchronize device datetime with local system time."""
        self.set_time(datetime.now())

    # ─── User Management ───────────────────────────────────────────────────────

    def list_users(self) -> List[User]:
        """Fetch all users registered on the device."""
        with self._device_locked():
            logger.debug("Fetching users from %s...", self.ip)
            raw_users = self.conn.get_users()
            return [
                User(
                    uid=u.uid,
                    user_id=str(u.user_id),
                    name=str(u.name or ""),
                    privilege=int(u.privilege or 0),
                    password=str(u.password or ""),
                    card=int(getattr(u, "card", 0) or 0),
                    group_id=str(getattr(u, "group_id", "") or ""),
                )
                for u in raw_users
            ]

    def get_user(self, user_identifier: Union[str, int]) -> Optional[User]:
        """Find a single user by user_id or uid."""
        users = self.list_users()
        str_id = str(user_identifier)
        for u in users:
            if u.user_id == str_id or (
                isinstance(user_identifier, int) and u.uid == user_identifier
            ):
                return u
        return None

    def add_user(
        self,
        uid: int,
        name: str,
        user_id: Union[str, int],
        password: str = "",
        privilege: int = consts.USER_DEFAULT,
        card: int = 0,
        department: str = "",
    ) -> None:
        """
        Create or update a user on the terminal.

        uid: Internal integer hardware UID.
        user_id: Badge / employee ID.
        department: Populates native device group_id field.
        card: Numeric RFID card number (0 = no card).
        """
        with self._device_locked():
            logger.info(
                "Adding/updating user uid=%s, user_id=%s, name='%s' on %s...",
                uid,
                user_id,
                name,
                self.ip,
            )
            self.conn.set_user(
                uid=uid,
                name=name,
                privilege=privilege,
                password=str(password or ""),
                user_id=str(user_id),
                card=int(card or 0),
                group_id=str(department or ""),
            )
            self.conn.refresh_data()

    def delete_user(self, uid: int = 0, user_id: Union[str, int] = "") -> None:
        """Remove a user by internal uid or external user_id."""
        with self._device_locked():
            logger.info(
                "Deleting user uid=%s, user_id=%s on %s...", uid, user_id, self.ip
            )
            self.conn.delete_user(uid=uid, user_id=str(user_id))
            self.conn.refresh_data()

    def find_user_by_card(self, card_number: int) -> Optional[User]:
        """Find user with the corresponding RFID card number."""
        for user in self.list_users():
            if user.card == card_number:
                return user
        return None

    def list_users_by_department(self, department: str) -> List[User]:
        """Filter users belonging to a specific department (group_id)."""
        return [u for u in self.list_users() if u.group_id == str(department)]

    def list_departments(self) -> List[str]:
        """Return unique list of non-empty departments (group_id) found on device."""
        depts = {u.group_id for u in self.list_users() if u.group_id}
        return sorted(depts)

    # ─── Fingerprint Biometrics Management ─────────────────────────────────────

    def get_all_templates(self) -> List[FingerprintTemplate]:
        """Retrieve all fingerprint templates stored on the device."""
        self._ensure_connected()
        logger.debug("Reading all fingerprint templates from %s...", self.ip)
        raw_templates = self.conn.get_templates()
        return [
            FingerprintTemplate(
                uid=getattr(t, "uid", 0),
                fid=getattr(t, "fid", 0),
                size=getattr(t, "size", 0),
                valid=getattr(t, "valid", 1),
                template=str(getattr(t, "template", "")),
            )
            for t in raw_templates
        ]

    def get_user_template(
        self, uid: int, temp_id: int = 0
    ) -> Optional[FingerprintTemplate]:
        """Retrieve a specific fingerprint template (0..9) for a user."""
        self._ensure_connected()
        raw = self.conn.get_user_template(uid=uid, temp_id=temp_id)
        if raw is None:
            return None
        return FingerprintTemplate(
            uid=getattr(raw, "uid", uid),
            fid=getattr(raw, "fid", temp_id),
            size=getattr(raw, "size", 0),
            valid=getattr(raw, "valid", 1),
            template=str(getattr(raw, "template", "")),
        )

    def save_user_template(self, user: Any, fingers: List[Any]) -> None:
        """Write/restore fingerprint templates for a user."""
        with self._device_locked():
            logger.info(
                "Saving %d fingerprint template(s) for user on %s...",
                len(fingers),
                self.ip,
            )
            self.conn.save_user_template(user, fingers)

    def delete_user_template(self, uid: int, temp_id: int = 0) -> Any:
        """Delete a single finger template from a user without removing the user account."""
        self._ensure_connected()
        logger.info(
            "Deleting fingerprint template uid=%s, temp_id=%s on %s...",
            uid,
            temp_id,
            self.ip,
        )
        return self._safe_call("delete_user_template", uid=uid, temp_id=temp_id)

    def enroll_user(self, uid: int, temp_id: int = 0) -> bool:
        """
        Put the device into remote fingerprint enrollment mode for the given user.
        The user must physically place their finger on the sensor.
        """
        self._ensure_connected()
        logger.info(
            "Initiating remote fingerprint enrollment for uid=%s (finger %s) on %s...",
            uid,
            temp_id,
            self.ip,
        )
        try:
            self.conn.delete_user_template(uid, temp_id)
        except Exception:
            pass

        self.conn.reg_event(consts.EVENT_REG_ALL)
        success = bool(self.conn.enroll_user(uid, temp_id))
        self.conn.refresh_data()
        return success

    def backup_user_with_templates(
        self, uid: int
    ) -> Tuple[User, List[FingerprintTemplate]]:
        """Fetch user data along with all their enrolled fingerprint templates."""
        user = self.get_user(uid)
        if user is None:
            raise ZKUserNotFoundError(uid)

        all_templates = self.get_all_templates()
        user_templates = [t for t in all_templates if t.uid == uid]
        return user, user_templates

    def bulk_restore_users_and_templates(self, user_template_pairs: List[Any]) -> None:
        """Bulk restore users and fingerprint templates using High-Rate protocol."""
        self._ensure_connected()
        logger.info(
            "Bulk restoring %d user-template pairs on %s...",
            len(user_template_pairs),
            self.ip,
        )
        self.conn.HR_save_usertemplates(user_template_pairs)

    # ─── Attendance Records / Logs ─────────────────────────────────────────────

    def get_attendance(self, limit: Optional[int] = None) -> List[AttendanceRecord]:
        """Retrieve stored attendance logs from the device."""
        self._ensure_connected()
        logger.debug("Reading attendance logs from %s...", self.ip)
        raw_records = self.conn.get_attendance()
        records = [
            AttendanceRecord(
                user_id=str(r.user_id),
                timestamp=r.timestamp,
                status=int(r.status),
                punch=int(r.punch),
                uid=getattr(r, "uid", None),
            )
            for r in raw_records
        ]
        if limit is not None and limit > 0:
            return records[-limit:]
        return records

    def clear_attendance(self) -> None:
        """Clear all stored attendance logs from the device."""
        self._ensure_connected()
        logger.warning("Clearing all attendance logs on %s...", self.ip)
        self.conn.clear_attendance()

    # ─── Real-Time Live Capture ────────────────────────────────────────────────

    def watch_live_events(
        self,
        on_event: Optional[Callable[[LiveAccessEvent], None]] = None,
        new_timeout: Optional[int] = None,
        enforce_rules: bool = False,
    ) -> None:
        """
        Listen for access punches in real time (blocking generator loop).

        on_event: Callback invoked on each valid event.
        enforce_rules: If True, evaluates event against self.rules registry.
        """
        self._ensure_connected()
        logger.info("Registering real-time live capture on %s...", self.ip)
        self.conn.reg_event(consts.EVENT_REG_ALL)

        capture_args: Dict[str, Any] = {}
        if new_timeout is not None:
            capture_args["new_timeout"] = new_timeout

        try:
            for raw_att in self.conn.live_capture(**capture_args):
                if raw_att is None:
                    continue

                att = AttendanceRecord(
                    user_id=str(raw_att.user_id),
                    timestamp=raw_att.timestamp,
                    status=int(raw_att.status),
                    punch=int(raw_att.punch),
                    uid=getattr(raw_att, "uid", None),
                )

                allowed = None
                area_name = None
                verdict = None
                if enforce_rules:
                    allowed = self.rules.is_access_allowed(att.user_id, att.timestamp)
                    area = self.rules.get_user_area(att.user_id)
                    area_name = area.name if area else None
                    verdict = "OK" if allowed else "ACCESS_DENIED_OUT_OF_SCHEDULE"

                event = LiveAccessEvent(
                    attendance=att,
                    allowed=allowed,
                    area_name=area_name,
                    verdict=verdict,
                )

                if on_event:
                    on_event(event)
                else:
                    logger.info(
                        "Access Event: user_id=%s, time=%s, verdict=%s",
                        att.user_id,
                        att.timestamp,
                        verdict or "N/A",
                    )

        except KeyboardInterrupt:
            logger.info("Live capture interrupted by user.")
        except ZKErrorResponse as exc:
            logger.error("Protocol error during live capture on %s: %s", self.ip, exc)
            raise ZKDeviceError(f"Live capture error: {exc}") from exc
        finally:
            self.conn.end_live_capture = True
            try:
                self.conn.enable_device()
            except Exception:
                pass

    def cancel_capture(self) -> Any:
        """Cancel an in-progress capture/enrollment and return to idle."""
        self._ensure_connected()
        return self._safe_call("cancel_capture")

    # ─── Hardware Actions & Audio ──────────────────────────────────────────────

    def unlock_door(self, seconds: int = 5) -> Any:
        """Pulse the relay output to unlock the door for the given duration in seconds."""
        self._ensure_connected()
        logger.info("Unlocking door relay for %d seconds on %s...", seconds, self.ip)
        return self._safe_call("unlock", seconds)

    def test_voice(self, index: int = 0) -> Any:
        """Play a pre-recorded voice audio prompt on the device speaker."""
        self._ensure_connected()
        voice_desc = consts.VOICE_MESSAGES.get(index, "Unknown")
        logger.info("Playing voice index=%s (%s) on %s...", index, voice_desc, self.ip)
        return self._safe_call("test_voice", index)

    # ─── Device Maintenance ────────────────────────────────────────────────────

    def restart_device(self) -> None:
        """Reboot the ZKTeco device."""
        self._ensure_connected()
        logger.warning("Rebooting device %s...", self.ip)
        self.conn.restart()

    def poweroff_device(self) -> None:
        """Power off the ZKTeco device."""
        self._ensure_connected()
        logger.warning("Powering off device %s...", self.ip)
        self.conn.poweroff()

    def free_buffer(self) -> Any:
        """Release bulk data read buffers on the device."""
        self._ensure_connected()
        return self._safe_call("free_data")

    def clear_all_data(self) -> None:
        """DANGER: Clear all users, fingerprints, and attendance logs on the device."""
        self._ensure_connected()
        logger.warning("CLEARING ALL DATA on device %s...", self.ip)
        self.conn.clear_data()


# Alias for backward compatibility with zk_adapter.py
ZKAdapter = ZKClient
